import React, { useEffect, useMemo, useRef, useState } from "react"
import { graphql, PageProps } from "gatsby"
import { getImage } from "gatsby-plugin-image"
import type { IGatsbyImageData } from "gatsby-plugin-image"
import { Article } from "@phosphor-icons/react"
import Layout from "../components/layout"
import SEO from "../components/seo"
import { ArticleListItem } from "../components/blog"
import IconWrapper from "../components/icons/IconWrapper"

interface PostNode {
  node: {
    excerpt: string
    fields: {
      slug: string
      /** 正文第一张本地图片（gatsby-node 提取并链接到 File 节点） */
      coverImage?: {
        publicURL?: string
        extension?: string
        childImageSharp?: {
          gatsbyImageData: IGatsbyImageData
        }
      }
    }
    frontmatter: {
      date: string
      rawDate: string
      title: string
      description?: string
      tags?: string[]
    }
    wordCount: {
      words: number
    }
  }
}

interface BlogPageData {
  site: {
    siteMetadata: {
      title: string
    }
  }
  allMarkdownRemark: {
    edges: PostNode[]
  }
}

interface MonthGroup {
  /** 形如 "03" */
  month: string
  posts: PostNode[]
}

interface YearGroup {
  year: string
  months: MonthGroup[]
  count: number
}

const SCROLL_OFFSET = 96

// slug 形如 /post/{year}/{name}/，兜底用原始日期解析年份与月份
function parseYearMonth(post: PostNode["node"]): { year: string; month: string } {
  const match = /^(\d{4})-(\d{2})/.exec(post.frontmatter.rawDate || "")
  if (match) {
    return { year: match[1], month: match[2] }
  }
  const yearFromSlug = post.fields.slug.split("/")[2]
  return {
    year: /^\d{4}$/.test(yearFromSlug) ? yearFromSlug : "未知",
    month: "00",
  }
}

function monthSectionId(year: string, month: string): string {
  return `m-${year}-${month}`
}

function yearSectionId(year: string): string {
  return `y-${year}`
}

const BlogPage: React.FC<PageProps<BlogPageData>> = ({ data, location }) => {
  const siteTitle = data.site.siteMetadata.title
  const posts = data.allMarkdownRemark.edges

  // 按 年 -> 月 分组，均倒序（查询已按日期倒序，组内顺序天然保持）
  const yearGroups = useMemo<YearGroup[]>(() => {
    const yearMap = new Map<string, Map<string, PostNode[]>>()
    posts.forEach((post) => {
      const { year, month } = parseYearMonth(post.node)
      if (!yearMap.has(year)) yearMap.set(year, new Map())
      const monthMap = yearMap.get(year)!
      if (!monthMap.has(month)) monthMap.set(month, [])
      monthMap.get(month)!.push(post)
    })
    return Array.from(yearMap.entries())
      .sort((a, b) => b[0].localeCompare(a[0]))
      .map(([year, monthMap]) => {
        const months = Array.from(monthMap.entries())
          .sort((a, b) => b[0].localeCompare(a[0]))
          .map(([month, monthPosts]) => ({ month, posts: monthPosts }))
        return {
          year,
          months,
          count: months.reduce((sum, m) => sum + m.posts.length, 0),
        }
      })
  }, [posts])

  // 所有月份锚点 id，按页面出现顺序（倒序时间）
  const monthAnchors = useMemo(
    () =>
      yearGroups.flatMap((g) =>
        g.months.map((m) => ({
          id: monthSectionId(g.year, m.month),
          year: g.year,
          month: m.month,
        }))
      ),
    [yearGroups]
  )

  const [activeMonthId, setActiveMonthId] = useState<string | null>(
    monthAnchors[0]?.id ?? null
  )
  const activeYear = useMemo(() => {
    const active = monthAnchors.find((a) => a.id === activeMonthId)
    return active?.year ?? yearGroups[0]?.year ?? null
  }, [activeMonthId, monthAnchors, yearGroups])

  // 滚动联动：找到当前滚动位置对应的最后一个月份分组
  const tickingRef = useRef(false)
  useEffect(() => {
    const updateActive = () => {
      tickingRef.current = false
      let current: string | null = null
      for (const anchor of monthAnchors) {
        const el = document.getElementById(anchor.id)
        if (!el) continue
        if (el.getBoundingClientRect().top <= SCROLL_OFFSET + 16) {
          current = anchor.id
        } else {
          break
        }
      }
      // 还没滚到第一个分组时，高亮第一个
      setActiveMonthId(current ?? monthAnchors[0]?.id ?? null)
    }
    const handleScroll = () => {
      if (!tickingRef.current) {
        tickingRef.current = true
        window.requestAnimationFrame(updateActive)
      }
    }
    updateActive()
    window.addEventListener("scroll", handleScroll, { passive: true })
    return () => window.removeEventListener("scroll", handleScroll)
  }, [monthAnchors])

  const scrollToSection = (id: string, behavior: ScrollBehavior = "smooth") => {
    const el = document.getElementById(id)
    if (!el) return
    const top = el.getBoundingClientRect().top + window.scrollY - SCROLL_OFFSET
    window.scrollTo({ top, behavior })
  }

  // 跨页面锚点跳转（如首页「查看更多」带的 #m-YYYY-MM）：
  // Gatsby 不会按 sticky 头部偏移滚动，挂载后手动定位并让侧栏高亮跟随
  useEffect(() => {
    const match = /^#m-\d{4}-\d{2}$/.exec(location.hash)
    if (!match) return
    const id = location.hash.slice(1)
    const raf = window.requestAnimationFrame(() => {
      if (!document.getElementById(id)) return
      scrollToSection(id, "instant")
      setActiveMonthId(id)
    })
    return () => window.cancelAnimationFrame(raf)
    // 仅在挂载时处理一次
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return (
    <Layout location={location} title={siteTitle}>
      <SEO title="文章" keywords={[`blog`, `gatsby`, `javascript`, `react`]} />

      <section>
        {/* Section Header */}
        <div className="flex items-center gap-2 mb-5 fade-in">
          <IconWrapper
            icon={Article}
            size={20}
            className="text-accent"
            weight="duotone"
          />
          <h2 className="text-lg font-bold text-foreground font-serif">文章</h2>
          {posts.length > 0 && (
            <span className="ml-2 text-xs text-foreground-secondary">
              (共 {posts.length} 篇)
            </span>
          )}
        </div>

        {posts.length === 0 ? (
          /* Empty State */
          <div className="text-center py-16 px-4 bg-background-card rounded-2xl fade-in">
            <div className="flex justify-center mb-4">
              <div className="w-14 h-14 rounded-full bg-accent-subtle flex items-center justify-center">
                <IconWrapper
                  icon={Article}
                  size={28}
                  className="text-accent"
                  weight="duotone"
                />
              </div>
            </div>
            <h3 className="text-base font-medium text-foreground mb-2">
              暂无文章
            </h3>
            <p className="text-sm text-foreground-muted">
              精彩内容正在筹备中，敬请期待...
            </p>
          </div>
        ) : (
          <div className="lg:grid lg:grid-cols-[minmax(0,1fr)_12rem] lg:gap-10">
            {/* 文章列表：按年、月分组 */}
            <div className="min-w-0">
              {yearGroups.map((group) => (
                <div
                  key={group.year}
                  id={yearSectionId(group.year)}
                  className="mb-8 last:mb-0"
                >
                  {/* Year Header */}
                  <div className="flex items-baseline gap-2 mb-3 px-1">
                    <h3 className="text-base font-bold text-foreground font-serif">
                      {group.year}
                    </h3>
                    <span className="text-xs text-foreground-secondary">
                      · {group.count} 篇
                    </span>
                  </div>

                  {group.months.map((monthGroup) => (
                    <div
                      key={monthGroup.month}
                      id={monthSectionId(group.year, monthGroup.month)}
                      className="mb-4 last:mb-0"
                    >
                      {/* Month Header */}
                      <div className="flex items-baseline gap-2 mb-2 px-1">
                        <h4 className="text-sm font-semibold text-foreground-secondary tabular-nums">
                          {monthGroup.month === "00"
                            ? "未注明月份"
                            : `${Number(monthGroup.month)} 月`}
                        </h4>
                        <span className="text-xs text-foreground-muted">
                          {monthGroup.posts.length} 篇
                        </span>
                      </div>

                      {/* Article List - 使用色块区分，无边框 */}
                      <div className="bg-background-card rounded-2xl p-3 sm:p-4">
                        {monthGroup.posts.map(({ node }, index) => {
                          const title =
                            node.frontmatter.title || node.fields.slug
                          // 列表封面：svg/gif 走 publicURL 原图，其余位图走 sharp
                          const cover = node.fields.coverImage
                          const ext = cover?.extension?.toLowerCase()
                          const thumb =
                            ext === "svg" || ext === "gif"
                              ? null
                              : getImage(cover?.childImageSharp ?? null)
                          const thumbUrl =
                            thumb == null ? cover?.publicURL ?? null : null
                          return (
                            <ArticleListItem
                              key={node.fields.slug}
                              slug={node.fields.slug}
                              title={title}
                              thumb={thumb}
                              thumbUrl={thumbUrl}
                              date={node.frontmatter.date}
                              description={node.frontmatter.description}
                              excerpt={node.excerpt}
                              tags={node.frontmatter.tags}
                              index={index}
                              wordCount={node.wordCount.words}
                            />
                          )
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              ))}
            </div>

            {/* 时间轴侧栏（桌面端） */}
            <aside className="hidden lg:block">
              <nav
                className="sticky top-24 max-h-[calc(100vh-8rem)] overflow-y-auto pr-1"
                aria-label="文章时间轴"
              >
                <ul className="relative border-l border-theme pl-4 space-y-1">
                  {yearGroups.map((group) => {
                    const isActiveYear = group.year === activeYear
                    return (
                      <li key={group.year}>
                        {/* Year */}
                        <button
                          type="button"
                          onClick={() =>
                            scrollToSection(yearSectionId(group.year))
                          }
                          className="group relative flex items-baseline gap-2 w-full text-left py-1"
                        >
                          {/* Year dot */}
                          <span
                            className={`absolute left-[-21px] top-1/2 -translate-y-1/2 w-2.5 h-2.5 rounded-full border-2 transition-colors duration-200 ${
                              isActiveYear
                                ? "bg-accent border-accent"
                                : "bg-background border-theme group-hover:border-accent"
                            }`}
                            aria-hidden="true"
                          />
                          <span
                            className={`text-sm tabular-nums transition-colors duration-200 ${
                              isActiveYear
                                ? "font-bold text-accent"
                                : "font-medium text-foreground-secondary group-hover:text-accent"
                            }`}
                          >
                            {group.year}
                          </span>
                          <span className="text-[11px] text-foreground-muted">
                            {group.count}
                          </span>
                        </button>

                        {/* Months - 仅展开当前年份，滚动时联动收起/展开 */}
                        <div
                          className={`grid transition-all duration-300 ease-out ${
                            isActiveYear
                              ? "grid-rows-[1fr] opacity-100"
                              : "grid-rows-[0fr] opacity-0"
                          }`}
                        >
                          <ul className="overflow-hidden">
                            {group.months.map((monthGroup) => {
                              const id = monthSectionId(
                                group.year,
                                monthGroup.month
                              )
                              const isActiveMonth = id === activeMonthId
                              return (
                                <li key={monthGroup.month}>
                                  <button
                                    type="button"
                                    onClick={() => scrollToSection(id)}
                                    className="group relative flex items-baseline gap-2 w-full text-left py-0.5 pl-3"
                                  >
                                    {/* Month dot */}
                                    <span
                                      className={`absolute left-0 top-1/2 -translate-y-1/2 w-1.5 h-1.5 rounded-full transition-colors duration-200 ${
                                        isActiveMonth
                                          ? "bg-accent"
                                          : "bg-border group-hover:bg-accent"
                                      }`}
                                      aria-hidden="true"
                                    />
                                    <span
                                      className={`text-xs tabular-nums transition-colors duration-200 ${
                                        isActiveMonth
                                          ? "font-semibold text-accent"
                                          : "text-foreground-secondary group-hover:text-accent"
                                      }`}
                                    >
                                      {monthGroup.month === "00"
                                        ? "未注明"
                                        : `${Number(monthGroup.month)} 月`}
                                    </span>
                                    <span className="text-[11px] text-foreground-muted">
                                      {monthGroup.posts.length}
                                    </span>
                                  </button>
                                </li>
                              )
                            })}
                          </ul>
                        </div>
                      </li>
                    )
                  })}
                </ul>
              </nav>
            </aside>
          </div>
        )}
      </section>
    </Layout>
  )
}

export default BlogPage

export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        title
      }
    }
    allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: {
        frontmatter: { published: { ne: false } }
        fileAbsolutePath: { regex: "/content/blog/" }
      }
    ) {
      edges {
        node {
          excerpt
          fields {
            slug
            coverImage {
              publicURL
              extension
              childImageSharp {
                gatsbyImageData(
                  width: 240
                  placeholder: BLURRED
                  formats: [AUTO, WEBP]
                )
              }
            }
          }
          frontmatter {
            date(formatString: "MMMM DD, YYYY")
            rawDate: date
            title
            description
            tags
          }
          wordCount {
            words
          }
        }
      }
    }
  }
`
